import{_ as r,l,o as e,c as t,v as n,p as d,x as o,d as s,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"全球金融周期","description":"","frontmatter":{"title":"全球金融周期","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/global-financial-cycle.md","filePath":"econ/global-financial-cycle.md","lastUpdated":1789023840000}'),E={name:"econ/global-financial-cycle.md"};function B(m,a,h,A,_,u){const i=l("Mermaid");return e(),t("div",null,[a[1]||(a[1]=n('<h1 id="全球金融周期" tabindex="-1">全球金融周期 <a class="header-anchor" href="#全球金融周期" aria-label="Permalink to &quot;全球金融周期&quot;">​</a></h1><div class="epigraph"><p>中心国家的货币与风险偏好，经跨境信贷与资产价格共动，把外围的金融条件焊在一起——三元悖论变成两难。</p><footer>—— Rey, Dilemma not Trilemma, 2013/2015；Miranda-Agrippino and Rey；Bruno and Shin 的跨境银行</footer></div><p><a href="/econ/macroprudential">上一课</a>的杠杆外部性写在一国。资本流动把周期变成全球。本课缺口是 <strong>Rey 的全球金融周期</strong>：VIX、美元、跨境信贷共动。不重写最优 LTV 公式，不把国际货币史提前写到美元主导课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开放宏观的三元：汇率稳定、独立货币、资本流动三者不可兼得。Rey：即使汇率浮动，全球风险因子仍驱动国内信贷与资产价格，货币政策独立性被打折。Bruno–Shin：全球银行杠杆、美元融资。缺口是把 GK 的中介从封闭经济接到跨境批发融资，而不是重写 UIP 实证（量化栏）。</p><p><span class="marginnote">Rey, Jackson Hole 2013。Miranda-Agrippino and Rey。Bruno and Shin, <em>ReStud</em> 2015。Cetorelli and Goldberg 的全球银行内部市场。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>因子：从各国风险资产、信贷、资本流抽一个全球因子，与 VIX、美元指数相关。结构：中心国利率与风险偏好进全球银行的杠杆约束，外围信贷供给外生松紧。政策：资本流动管理作为宏观审慎的跨境工具；外汇干预；本地货币 vs 美元债（原罪）。识别：中心国货币冲击的外溢用高频或叙事，外围是接收者。</p>',8)),(e(),d(c,null,{default:o(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CTR%5B%22%E4%B8%AD%E5%BF%83%E8%B4%A7%E5%B8%81%20%2F%20%E9%A3%8E%E9%99%A9%E5%81%8F%E5%A5%BD%22%5D%20--%3E%20LEV%5B%22%E5%85%A8%E7%90%83%E4%B8%AD%E4%BB%8B%E6%9D%A0%E6%9D%86%22%5D%0A%20%20LEV%20--%3E%20FLOW%5B%22%E8%B7%A8%E5%A2%83%E4%BF%A1%E8%B4%B7%22%5D%0A%20%20FLOW%20--%3E%20PER%5B%22%E5%A4%96%E5%9B%B4%E4%BF%A1%E8%B4%B7%E4%B8%8E%E6%88%BF%E4%BB%B7%22%5D%0A%20%20FLOAT%5B%22%E6%B5%AE%E5%8A%A8%E6%B1%87%E7%8E%87%22%5D%20--%3E%20PART%5B%22%E5%8F%AA%E9%83%A8%E5%88%86%E7%BB%9D%E7%BC%98%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>与 HANK：外围家庭若有外汇债，全球周期直接进实际负担（债务通缩的外汇版）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是全球净值与以美元计价的约束。美元升值恶化新兴市场企业与银行的外汇债净值，收紧 GK 约束，即使本地政策利率不动。浮动汇率缓冲贸易，不自动缓冲金融。这与 KM 的 \\(q\\) 循环同构，价格换成全球风险资产与汇率。</p><p>诊断性与不确定性：全球 \\(\\sigma\\) 冲击（Bloom 的国际版）同时收紧所有杠杆。新闻：中心国前瞻指引是全球新闻冲击。</p><p><span class="marginnote">Obstfeld 对三元的辩护：浮动仍给部分货币空间。本课记录争论，不假装已有唯一计量结论。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计 carry trade 策略。不把每一国的资本管制写成最优税率表。美元为何是中心货币，留到本单元最后一课。主权违约下一课换对象：政府而不是银行。</p><p>后课默认：浮动汇率不自动买来金融独立；全球因子经中介杠杆传导。下一课：主权不能抵押时如何借。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全球金融周期：中心风险偏好与美元驱动跨境信贷共动。</li><li>浮动汇率对金融条件只部分绝缘。</li><li>资本流动管理是跨境宏观审慎。</li><li>出处：Rey, Dilemma not Trilemma；Bruno and Shin；Miranda-Agrippino and Rey。</li></ul>',10))])}const b=r(E,[["render",B]]);export{T as __pageData,b as default};
